DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT103-S3-Q16$batch05$ AND q.stimulus=$batch05$The recently negotiated North American Free Trade Agreement among Canada, Mexico, and the United States is misnamed, because it would not result in truly free trade. Adam Smith, the economist who first articulated the principles of free trade held that any obstacle placed in the way of the free movement of goods, investment, or labor would defeat free trade. So since under the agreement workers would be restricted by national boundaries from seeking the best conditions they could find, the resulting obstruction of the flow of trade would, from a free- trade perspective, be harmful.$batch05$ AND q.prompt=$batch05$The argument proceeds by$batch05$ AND q.correct_choice=$batch05$D$batch05$) THEN RAISE EXCEPTION 'Question changed: PT103-S3-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT103-S3-Q16$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S3-Q16'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT103-S3-Q16$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$The North American Free Trade Agreement is misnamed, because it would not create truly free trade.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Adam Smith, who first set out the principles of free trade, held that any obstacle to the free movement of goods, investment or labor defeats free trade. Under the agreement, workers would be held back by national borders.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$What gives the author the right to define free trade this way? Adam Smith, the economist who first spelled it out. The author borrows Smith's standard and applies it to the agreement. That is an appeal to authority, and here the authority is relevant: Smith is the right person to ask about what free trade means.$batch05$), (3, $batch05$Goal$batch05$, $batch05$An appeal to a relevant authority.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT103-S3-Q16$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$No list of alternatives is narrowed down.$batch05$), ($batch05$B$batch05$, $batch05$This is the top trap, chosen by about one student in six, because the argument is all about whether a name fits. But "free trade" means the same thing throughout: Smith's sense. The author applies one definition consistently. They do not slide between two meanings.$batch05$), ($batch05$C$batch05$, $batch05$Restricting workers is not an unrepresentative example. It is the very feature that fails Smith's test.$batch05$), ($batch05$D$batch05$, $batch05$Smith is the authority, and he is relevant because he first articulated the principle at issue.$batch05$), ($batch05$E$batch05$, $batch05$The issue is whether the agreement creates free trade, and that is exactly what the author addresses.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT103-S3-Q16$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
